mapper.select:
SELECT cr.roomIdx FROM chatRoom cr
JOIN chatMember m1 ON cr.roomIdx = m1.roomIdx AND m1.userIdx = #{userIdxA}
JOIN chatMember m2 ON cr.roomIdx = m2.roomIdx AND m2.userIdx = #{userIdxB}
WHERE cr.roomType = 3 AND ROWNUM = 1

mapper.update:
UPDATE users
SET is_online = #{isOnline}
WHERE userIdx = #{userIdx}

mapper.select:
SELECT NVL(is_online, 0)
FROM users
WHERE userIdx = #{userIdx}
